// Cloudflare Worker entry. dist/games.js is generated by build.mjs from the game cores (wrangler runs it first).
import { GAMES } from '../dist/games.js';
import { createHandler } from './handler.js';
import { dispatch } from './dispatch.js';

const handle = createHandler(GAMES);
export default {
  fetch: (request, env) => handle(request, env),
  scheduled: (event, env, ctx) => ctx.waitUntil(dispatch(env).then(r => console.log(JSON.stringify(r)))),
};
